CREATE TABLE IF NOT EXISTS "MatchReaction" ("id" SERIAL PRIMARY KEY, "matchId" INTEGER NOT NULL REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE, "userId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, "emoji" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX IF NOT EXISTS "MatchReaction_matchId_userId_key" ON "MatchReaction"("matchId", "userId");
CREATE TABLE IF NOT EXISTS "MatchComment" ("id" SERIAL PRIMARY KEY, "matchId" INTEGER NOT NULL REFERENCES "Match"("id") ON DELETE CASCADE ON UPDATE CASCADE, "userId" INTEGER NOT NULL REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE, "text" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "hiddenAt" TIMESTAMP(3), "hiddenBy" INTEGER);
CREATE INDEX IF NOT EXISTS "MatchComment_matchId_createdAt_idx" ON "MatchComment"("matchId", "createdAt");
